<?php require_once __DIR__.'/../config/db.php';$token=preg_replace('/[^a-f0-9]/i','',$_GET['token']??'');if(strlen($token)!==32)jsonResponse(false,'Invalid TV token.');$db=getDB();$c=$db->prepare('SELECT * FROM clubs WHERE tv_token=?');$c->execute([$token]);$club=$c->fetch();if(!$club)jsonResponse(false,'Invalid TV token.');$q=$db->prepare("SELECT t.id,t.table_number,t.table_type,t.status,s.player_name_walkin,s.start_time,s.total_pause_seconds,p.name player_name FROM tables t LEFT JOIN sessions s ON s.table_id=t.id AND s.status IN('running','paused') LEFT JOIN players p ON p.id=s.player_id WHERE t.club_id=? AND t.is_active=1 ORDER BY t.table_number");$q->execute([$club['id']]);$tables=$q->fetchAll();$q=$db->prepare("SELECT p.name,p.tier,SUM(s.total_amount) value FROM sessions s JOIN players p ON p.id=s.player_id WHERE s.club_id=? AND s.status='completed' AND s.end_time >= DATE_SUB(CURDATE(),INTERVAL 7 DAY) GROUP BY p.id ORDER BY value DESC LIMIT 10");$q->execute([$club['id']]);jsonResponse(true,'',['club_name'=>$club['name'],'tables'=>$tables,'leaderboard'=>$q->fetchAll(),'server_time'=>time()]);
